arguments.file_text:
@namespace sv_ec7ee36071e24cd0a679b9734bbbf78b.Components.Pages.Chat

<div class="message-list" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
    }
</div>

@code {
    [Parameter] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top detection is handled via JS interop in a real app.
        // For now, we expose the callback for the parent to trigger.
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.75rem;
    font-size: 0.85rem;
    color: #72767d;
}

@namespace sv_ec7ee36071e24cd0a679b9734bbbf78b.Components.Pages.Chat
@using sv_ec7ee36071e24cd0a679b9734bbbf78b.Services

<section class="message-area">
    <header class="area-header">
        <h2># @ChannelName</h2>
        <span class="channel-desc">@ChannelDescription</span>
    </header>

    <MessageList Messages="Messages"
                 ThreadReplyCounts="ThreadReplyCounts"
                 IsLoadingMore="IsLoadingMore"
                 OnOpenThread="OnOpenThread"
                 OnReact="OnReact"
                 OnLoadMore="OnLoadMore" />

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</section>

@code {
    [Parameter] public string ChannelName { get; set; } = string.Empty;
    [Parameter] public string ChannelDescription { get; set; } = string.Empty;
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
}

.area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #2e3338;
}

.channel-desc {
    font-size: 0.85rem;
    color: #72767d;
}

@namespace sv_ec7ee36071e24cd0a679b9734bbbf78b.Components.Pages.Chat
@using sv_ec7ee36071e24cd0a679b9734bbbf78b.Services

<aside class="thread-panel">
    <header class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </header>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="root-author">@RootMessage.Author</span>
            <p class="root-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="reply-header">
                        <span class="reply-author">@reply.Author</span>
                        <span class="reply-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="reply-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply..."
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</aside>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hr ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays} days ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    border-left: 1px solid #e3e5e8;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #2e3338;
}

.close-btn {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    color: #72767d;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f2f3f5;
    color: #2e3338;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #f2f3f5;
    background: #f9fafb;
}

.root-author {
    font-weight: 600;
    font-size: 0.85rem;
    color: #2e3338;
}

.root-content {
    margin: 0.25rem 0 0;
    font-size: 0.85rem;
    color: #4f5660;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.thread-reply {
    padding: 0.4rem 1rem;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 0.4rem;
}

.reply-author {
    font-weight: 600;
    font-size: 0.85rem;
    color: #2e3338;
}

.reply-time {
    font-size: 0.7rem;
    color: #72767d;
}

.reply-content {
    font-size: 0.85rem;
